-- 018: AI 참고답변을 댓글 수에 포함 (대표 지시 2026-11-10)
CREATE OR REPLACE FUNCTION public.bl_post_json(p bl_posts)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select jsonb_build_object('id',p.id,'is_sample',p.is_sample,'channel_id',p.channel_id,'channel_name',(select name from public.bl_channels where id=p.channel_id),'company_id',p.company_id,'company_name',(select name from public.bl_companies where id=p.company_id),'title',case when p.status='published' or public.bl_is_admin() or (p.author_id=auth.uid() and p.status='hidden') then p.title else '가려진 게시물' end,'body',case when p.status<>'published' and not public.bl_is_admin() and not (p.author_id=auth.uid() and p.status='hidden') then '' when p.content_kind='experience' and not(public.bl_verified() or public.bl_is_admin()) then left(p.body,300) else p.body end,'content_kind',p.content_kind,'is_question',p.is_question,'author_display',case when p.as_team then '보험라이브 운영팀' when p.anonymous then '익명' else public.bl_author(p.author_id,p.author_company,p.author_nickname) end,'as_team',p.as_team,'anonymous',p.anonymous,'pinned_order',p.pinned_order,'created_at',p.created_at,'updated_at',p.updated_at,'status',p.status,'pinned',p.pinned,'views',p.view_count,'likes',(select count(*) from public.bl_reactions r where r.target='post' and r.target_id=p.id and r.kind='like'),'comment_count',(select count(*) from public.bl_comments c where c.post_id=p.id and c.status='published' and public.bl_test_visible(c.is_test))+(select count(*) from public.bl_ai_replies a where a.post_id=p.id and a.status='published'),'liked',exists(select 1 from public.bl_reactions r where r.user_id=auth.uid() and r.target='post' and r.target_id=p.id and r.kind='like'),'bookmarked',exists(select 1 from public.bl_reactions r where r.user_id=auth.uid() and r.target='post' and r.target_id=p.id and r.kind='bookmark'),'is_mine',coalesce(p.author_id=auth.uid(),false),'is_truncated',p.content_kind='experience' and length(p.body)>300 and not(public.bl_verified() or public.bl_is_admin())); $function$;
